session_start();require_once '../shared/config.php';requireLogin('customer','login.php');$db=getDB();
$occasions=['Wedding','Haldi / Mehendi','Festival','College Fest','Traditional Day','Photoshoot'];
$occasion=trim($_GET['occasion']??'');if(!in_array($occasion,$occasions,true))$occasion='';
