if($occasion||$search){$terms=['Wedding'=>'wedding bridal groom lehenga saree sherwani','Haldi / Mehendi'=>'haldi mehendi yellow festive saree lehenga kurta','Festival'=>'festival traditional festive saree kurta lehenga sherwani','College Fest'=>'college fest kurta saree traditional','Traditional Day'=>'traditional day saree kurta ethnic','Photoshoot'=>'photoshoot designer traditional saree lehenga sherwani'];
$q=$search?:$terms[$occasion];$like='%'.$q.'%';$sql="SELECT i.*,v.store_name FROM items i JOIN vendors v ON v.id=i.vendor_id WHERE i.available=1 AND (i.name LIKE ? OR i.description LIKE ? OR i.category LIKE ?) ORDER BY i.name LIMIT 24";$st=$db->prepare($sql);$st->execute([$like,$like,$like]);$items=$st->fetchAll();}
