tems as $i):?><a class="item" href="item.php?id=<?=$i['id']?>"><div class="pic"><?php if($i['image_path']&&file_exists('../uploads/items/'.$i['image_path'])):?><img src="../uploads/items/<?=htmlspecialchars($i['image_path'])?>"><?php else:?>👘<?php endif;?></div><div class="body"><div class="name"><?=htmlspecialchars($i['name'])?></div><div class="store"><?=htmlspecialchars($i['store_name'])?></div><div class="small"><?=htmlspecialchars($i['category']??'Traditional wear')?> · ₹<?=number_format((float)$i['rent_per_day'],0)?>/day</div></div></a><?php endforeach;?></div><?php else:?><div class="empty">No catalogue items matched this occasion/search yet. Try another occasion or broader search.</div><?php endif;?><?php else:?><div class="empty">Select an occasion above to start exploring.</div><?php endif;?></main></body></html>